func:
var data=msg.payload;
if (Buffer.isBuffer(data)) data=data.toString('utf8');
if (typeof data==='string') {
    if (!data.trim()) return null;
    try { data=JSON.parse(data); }
    catch(e) { node.warn('Telemetry: JSON khong hop le'); return null; }
}
if (!data || typeof data!=='object' || Array.isArray(data)) return null;
var allowed=['OK','LOW_STOCK','ERR:OBJECT','SENSOR_ERROR'];
var status=String(data.alert_status||'').trim();
if (allowed.indexOf(status)===-1) return null;
var healthy=(data.sensor_ok!==false && status!=='SENSOR_ERROR');
var weight=Number(data.weight_g), qty=Number(data.quantity);
if (healthy && (!Number.isFinite(weight) || !Number.isFinite(qty))) {
    node.warn('Telemetry thieu weight_g/quantity hop le'); return null;
}
var device=String(data.device_id||'SHELF_01_SV3').slice(0,40);
var normalized={
    device_id:device,
    weight_g:healthy?weight:null,
    quantity:healthy?Math.max(0,Math.round(qty)):null,
    alert_status:status,
    sensor_ok:healthy,
    led_state:String(data.led_state||'UNKNOWN').slice(0,12),
    led_muted:data.led_muted===true,
    uptime_ms:Number.isFinite(Number(data.uptime_ms))?Number(data.uptime_ms):null
};
msg.kind='telemetry';
msg.payload=normalized;

// Send Telegram only when the alert state changes; repeated 2-second telemetry is suppressed.
var previous=flow.get('sv3_telegram_alert_status');
var telegramMsg=null;
if (status==='LOW_STOCK' || status==='ERR:OBJECT' || status==='SENSOR_ERROR') {
    if (previous!==status) {
        telegramMsg={payload:{event:'alert',device_id:device,status:status,
            weight_g:normalized.weight_g,quantity:normalized.quantity,sensor_ok:healthy,
            led_state:normalized.led_state}};
    }
} else if (status==='OK' && previous && previous!=='OK') {
    telegramMsg={payload:{event:'recovery',device_id:device,status:'OK',previous_status:previous,
        weight_g:normalized.weight_g,quantity:normalized.quantity,sensor_ok:healthy,
        led_state:normalized.led_state}};
}
flow.set('sv3_telegram_alert_status',status);
return [msg,telegramMsg];

var p=msg.payload;
if(!p.sensor_ok || !Number.isFinite(p.weight_g))return null;
msg.payload=p.weight_g;
msg.topic='Khối lượng (g)';
return msg;

var p=msg.payload;
if (Buffer.isBuffer(p)) p=p.toString('utf8');
if (typeof p!=='string') return null;
p=p.trim().toUpperCase();
if (p!=='ONLINE' && p!=='OFFLINE') return null;
var previous=flow.get('sv3_telegram_mqtt_last');
var seenOnline=flow.get('sv3_telegram_seen_online')===true;
var telegramMsg=null;
if (p==='ONLINE') {
    if (seenOnline && previous==='OFFLINE') {
        telegramMsg={payload:{event:'reconnected',device_id:'SHELF_01_SV3',status:'ONLINE'}};
    }
    flow.set('sv3_telegram_seen_online',true);
} else if (p==='OFFLINE' && seenOnline && previous!=='OFFLINE') {
    telegramMsg={payload:{event:'offline',device_id:'SHELF_01_SV3',status:'OFFLINE'}};
}
flow.set('sv3_telegram_mqtt_last',p);
msg.kind='status';
msg.payload=p;
return [msg,telegramMsg];

var state=flow.get('sv3_enh_team_view')||{
  has_data:false,weight_g:null,quantity:null,sensor_ok:null,
  alert_status:'WAITING',led_state:'UNKNOWN',led_muted:false,
  device_id:'SHELF_01_SV3',connection:'UNVERIFIED',
  last_data:'--',last_status:'--'
};
var now=new Date().toLocaleTimeString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour12:false});
if(msg.kind==='telemetry') {
 Object.assign(state,msg.payload);state.has_data=true;state.last_data=now;
} else if(msg.kind==='status') {
 state.connection=msg.payload;state.last_status=now;
} else return null;
flow.set('sv3_enh_team_view',state);
msg.payload=Object.assign({},state);
return msg;

var p=msg.payload;
if(Buffer.isBuffer(p))p=p.toString('utf8');
if(typeof p==='string'){
 if(!p.trim())return null;
 try{p=JSON.parse(p);}catch(e){node.warn('ACK: JSON khong hop le');return null;}
}
if(!p || typeof p!=='object'||Array.isArray(p)||!p.command||!p.result)return null;
msg.payload={command:String(p.command).slice(0,32),result:String(p.result).slice(0,45),source:String(p.source||'?').slice(0,32),time:new Date().toLocaleTimeString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour12:false})};
return msg;

var command=String(msg.payload||'').trim().toUpperCase();
if (command!=='TARE' && command!=='RESET_ALERT') return null;
var now=new Date().toLocaleTimeString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour12:false});
var publishMsg={topic:'smartretail/shelves/sv3_demo/commands',
    payload:JSON.stringify({command:command}),qos:0,retain:false};
var historyMsg={payload:{command:command,result:'ĐÃ GỬI (chờ ACK)',source:'DASHBOARD',time:now}};
return [publishMsg,historyMsg];

const token = env.get("TELEGRAM_BOT_TOKEN");
const chatId = env.get("TELEGRAM_CHAT_ID");
const p=msg.payload||{};
const now=new Date().toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'});
const device=String(p.device_id||'SHELF_01_SV3');
let text='';
if (p.event==='test') {
    text='🧪 SMART SHELF SV3 - TEST TELEGRAM\nBot và Chat ID đã được cấu hình. Node-RED gửi tin nhắn thử thành công.\nThiết bị: '+device+'\nThời gian: '+now;
} else if (p.event==='offline') {
    text='🔴 SMART SHELF SV3 - MẤT KẾT NỐI\nThiết bị: '+device+'\nMQTT status: OFFLINE\nKiểm tra Wi-Fi, ESP32 và kết nối HiveMQ.\nThời gian: '+now;
} else if (p.event==='reconnected') {
    text='🟢 SMART SHELF SV3 - ĐÃ KẾT NỐI LẠI\nThiết bị: '+device+'\nMQTT status: ONLINE\nThiết bị đã kết nối lại với broker.\nThời gian: '+now;
} else if (p.event==='recovery') {
    text='✅ SMART SHELF SV3 - TRẠNG THÁI ĐÃ PHỤC HỒI\nThiết bị: '+device+'\nTrạng thái: OK (trước đó: '+String(p.previous_status||'ALERT')+')\nSố lượng: '+String(p.quantity==null?'--':p.quantity)+' lon\nKhối lượng: '+String(p.weight_g==null?'--':p.weight_g)+' g\nThời gian: '+now;
} else if (p.event==='alert' && p.status==='LOW_STOCK') {
    text='🚨 SMART SHELF SV3 - CẢNH BÁO TỒN KHO THẤP\nThiết bị: '+device+'\nTrạng thái: LOW_STOCK\nSố lượng: '+String(p.quantity==null?'--':p.quantity)+' lon\nKhối lượng: '+String(p.weight_g==null?'--':p.weight_g)+' g\nVui lòng kiểm tra và bổ sung hàng.\nThời gian: '+now;
} else if (p.event==='alert' && p.status==='ERR:OBJECT') {
    text='⚠️ SMART SHELF SV3 - KHỐI LƯỢNG BẤT THƯỜNG\nThiết bị: '+device+'\nTrạng thái: ERR:OBJECT\nKhối lượng: '+String(p.weight_g==null?'--':p.weight_g)+' g\nSố lượng ước tính: '+String(p.quantity==null?'--':p.quantity)+' lon\nKiểm tra vật thể/dị vật và cách đặt hàng trên kệ.\nThời gian: '+now;
} else if (p.event==='alert' && p.status==='SENSOR_ERROR') {
    text='🛠️ SMART SHELF SV3 - LỖI CẢM BIẾN\nThiết bị: '+device+'\nTrạng thái: SENSOR_ERROR\nHX711 không sẵn sàng hoặc cảm biến đang báo lỗi.\nKhông sử dụng số đo hiện tại để kết luận tồn kho.\nThời gian: '+now;
} else {
    return null;
}
if (!token || !chatId) {
    node.warn('Telegram chua cau hinh TELEGRAM_BOT_TOKEN / TELEGRAM_CHAT_ID');
    return [null,{payload:{telegram_ok:false,http_status:0,detail:'Chưa cấu hình TELEGRAM_BOT_TOKEN và/hoặc TELEGRAM_CHAT_ID trong môi trường Node-RED Docker.',event:String(p.event||'alert'),time:now,text:text}}];
}
msg.url='https://api.telegram.org/bot'+token+'/sendMessage';
msg.method='POST';
msg.headers={'Content-Type':'application/json'};
msg.telegram_event=String(p.event||'alert');
msg.telegram_text=text;
msg.payload={chat_id:String(chatId),text:text,disable_web_page_preview:true};
return [msg,null];

var body=msg.payload||{};
var ok=msg.statusCode===200 && body.ok===true;
var detail=ok?'Telegram đã gửi thành công.':String(body.description||('Telegram API trả HTTP '+String(msg.statusCode||'không rõ')));
return {payload:{telegram_ok:ok,http_status:Number(msg.statusCode)||0,detail:detail,
    event:String(msg.telegram_event||'alert'),time:new Date().toLocaleTimeString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour12:false}),
    text:String(msg.telegram_text||'')}};

var detail=(msg.error && msg.error.message)?String(msg.error.message):'Không thể kết nối Telegram API.';
detail=detail.replace(/https?:\/\/api\.telegram\.org\/bot[^\s/]+/gi,'Telegram API URL [ĐÃ ẨN TOKEN]');
return {payload:{telegram_ok:false,http_status:Number(msg.statusCode)||0,detail:detail.slice(0,220),
    event:String(msg.telegram_event||'alert'),time:new Date().toLocaleTimeString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour12:false}),
    text:String(msg.telegram_text||'')}};
